changeSet.sql:
ALTER TABLE app.WorkoutProgramDays DROP CONSTRAINT CK_WorkoutProgramDays_Number;
ALTER TABLE app.WorkoutProgramDays ADD CONSTRAINT CK_WorkoutProgramDays_Number CHECK (DayNumber BETWEEN 1 AND 31);

ALTER TABLE app.WorkoutPrograms ADD
    SourceAssessmentId UNIQUEIDENTIFIER NULL,
    PromptVersion NVARCHAR(40) NULL,
    GenerationModel NVARCHAR(100) NULL,
    PlanStartDate DATE NULL;
ALTER TABLE app.WorkoutPrograms ADD CONSTRAINT FK_WorkoutPrograms_FitnessAssessments FOREIGN KEY (SourceAssessmentId) REFERENCES app.FitnessAssessments (Id);

rollback.sql:
ALTER TABLE app.WorkoutPrograms DROP CONSTRAINT FK_WorkoutPrograms_FitnessAssessments;
ALTER TABLE app.WorkoutPrograms DROP COLUMN PlanStartDate, GenerationModel, PromptVersion, SourceAssessmentId;
ALTER TABLE app.WorkoutProgramDays DROP CONSTRAINT CK_WorkoutProgramDays_Number;
ALTER TABLE app.WorkoutProgramDays ADD CONSTRAINT CK_WorkoutProgramDays_Number CHECK (DayNumber BETWEEN 1 AND 14);
